test "t13 read whole file" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    try tmp.dir.writeFile(std.testing.io, .{ .sub_path = "a.txt", .data = "hola\nmundo\n" });
    try tmp.dir.writeFile(std.testing.io, .{ .sub_path = "vacio.txt", .data = "" });
    const got = try readWhole(std.testing.allocator, std.testing.io, tmp.dir, "a.txt");
    defer std.testing.allocator.free(got);
    try std.testing.expectEqualStrings("hola\nmundo\n", got);
    const empty = try readWhole(std.testing.allocator, std.testing.io, tmp.dir, "vacio.txt");
    defer std.testing.allocator.free(empty);
    try std.testing.expectEqual(@as(usize, 0), empty.len);
}
